    },
    {
      "question": "What are the specific HBM bandwidth utilization numbers or memory traffic measurements?",
      "terms": ["HBM bandwidth", "memory traffic", "bandwidth utilization", "GB/s"]
    },
    {
      "question": "What is the power consumption or performance-per-watt compared to dense baselines?",
      "terms": ["power", "energy", "W", "performance-per-watt", "efficiency"]
    }
  ]
}

